import Foundation

/// Third-party notices for the code, fonts and data this library distributes.
///
/// The index and the notice files are generated by `scripts/collect-notices` from
/// `notices/manifest.json`; run `make licenses` after changing a dependency.
public enum ThirdPartyNotices {
    public struct Component: Decodable, Identifiable, Hashable, Sendable {
        public let id: String
        public let name: String
        public let version: String?
        public let license: String
        public let source: String?
        public let role: String
        public let documents: [Document]
    }

    public struct Document: Decodable, Identifiable, Hashable, Sendable {
        public let title: String
        /// Path relative to the bundled `Bundled` directory.
        public let path: String

        public var id: String { path }
    }

    /// Every distributed component, in manifest order.
    public static func components() -> [Component] {
        guard let url = Bundle.module.url(forResource: "index", withExtension: "json", subdirectory: "Bundled/Notices"),
            let data = try? Data(contentsOf: url),
            let index = try? JSONDecoder().decode(Index.self, from: data)
        else {
            preconditionFailure("Missing bundled third-party notice index")
        }
        return index.components
    }

    /// The text of one notice document, or nil if the bundled file cannot be read.
    public static func text(of document: Document) -> String? {
        guard let index = Bundle.module.url(forResource: "index", withExtension: "json", subdirectory: "Bundled/Notices")
        else { return nil }
        let bundled = index.deletingLastPathComponent().deletingLastPathComponent()
        return try? String(contentsOf: bundled.appending(path: document.path), encoding: .utf8)
    }

    private struct Index: Decodable {
        let components: [Component]
    }
}
